-- Listado de deudores a la Hacienda Pública (art. 95 bis LGT), publicado por la AEAT el 30-06-2026.
-- Situación a 31-12-2025. Solo entidades con CIF (4.742). Las personas físicas del listado se descartan.
-- Extraído por OCR del PDF firmado el 22-07-2026 y verificado (CIF por dígito de control; importes por
-- reconocimiento de glifos y revisión manual de los dudosos). name_listed es el nombre tal cual lo lee el OCR:
-- para mostrar, usar el de companies.

CREATE TABLE IF NOT EXISTS aeat_debtors (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  cif VARCHAR(9) NOT NULL,
  list_year SMALLINT UNSIGNED NOT NULL,
  name_listed VARCHAR(255) NULL,
  amount_eur DECIMAL(15,2) NOT NULL,
  reference_date DATE NOT NULL,
  published_at DATE NOT NULL,
  source VARCHAR(40) NOT NULL DEFAULT 'AEAT_95BIS',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_aeat_debtors_cif_year (cif, list_year),
  KEY idx_aeat_debtors_year (list_year)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM aeat_debtors WHERE list_year = 2026 AND source = 'AEAT_95BIS';











